#[test]
fn wildcard_matches_glob() {
    let mut r = Rng(6);
    let mut yes = 0;
    for _ in 0..N {
        let p = text(&mut r, b"ab*?", 6);
        let n = text(&mut r, b"ab", 6);
        let got = wildmatch::is_match(&p, &n);
        assert_eq!(got, glob(&p, &n), "{p:?} {n:?}");
        yes += got as usize;
    }
    assert!(yes > MIN_HITS);
}
